import React, { useState, useEffect, useRef } from 'react';
import { useNavigate, useParams } from 'react-router-dom';
import { projectsAPI } from '../../services/api';
import AppLayout from '../../components/layout/AppLayout';
import toast from 'react-hot-toast';

const WEATHER_OPTIONS = [
  { value: 'ensoleille', label: '☀️ Ensoleillé' },
  { value: 'nuageux',   label: '☁️ Nuageux'   },
  { value: 'pluvieux',  label: '🌧️ Pluvieux'  },
  { value: 'venteux',   label: '💨 Venteux'   },
  { value: 'orageux',   label: '⛈️ Orageux'   },
];

export default function DailyReportFormPage() {
  const { id: projectId, reportId } = useParams();
  const navigate = useNavigate();
  const isEditing = Boolean(reportId);
  const fileInputRef = useRef();

  const [project, setProject]                 = useState(null);
  const [loading, setLoading]                 = useState(false);
  const [uploadingImages, setUploadingImages] = useState(false);
  const [pendingImages, setPendingImages]     = useState([]); 
  const [existingImages, setExistingImages]   = useState([]); 

  const [form, setForm] = useState({
    report_date:    new Date().toISOString().split('T')[0],
    weather:        'ensoleille',
    temperature:    '',
    workers_count:  0,
    work_done:      '',
    materials_used: '',
    incidents:      '',
    progress_pct:   '',
  });

  useEffect(() => {
    (async () => {
      try {
        const pRes = await projectsAPI.get(projectId);
        setProject(pRes.data);
        if (isEditing) {
          const rRes = await projectsAPI.getReport(projectId, reportId);
          const r = rRes.data;
          setForm({
            report_date:    r.report_date     || '',
            weather:        r.weather         || 'ensoleille',
            temperature:    r.temperature     ?? '',
            workers_count:  r.workers_count   ?? 0,
            work_done:      r.work_done       || '',
            materials_used: r.materials_used  || '',
            incidents:      r.incidents       || '',
            progress_pct:   r.progress_pct    ?? '',
          });
          setExistingImages(r.images || []);
        }
      } catch {
        toast.error('Erreur lors du chargement');
        navigate(`/projects/${projectId}`);
      }
    })();
  }, [projectId, reportId]);

  const handleChange = (e) => {
    const { name, value, type } = e.target;
    setForm(f => ({ ...f, [name]: type === 'number' ? (value === '' ? '' : Number(value)) : value }));
  };

  const handleFileSelect = (e) => {
    const files = Array.from(e.target.files);
    const newImages = files.map(file => ({ file, preview: URL.createObjectURL(file), caption: '' }));
    setPendingImages(prev => [...prev, ...newImages]);
  };

  const removePending = (index) => {
    setPendingImages(prev => prev.filter((_, i) => i !== index));
  };

  const removeExisting = async (imageId) => {
    try {
      await projectsAPI.deleteReportImage(projectId, reportId, imageId);
      setExistingImages(prev => prev.filter(img => img.id !== imageId));
      toast.success('Supprimé');
    } catch {
      toast.error('Erreur');
    }
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    setLoading(true);
    try {
      let savedId = reportId;
      if (isEditing) {
        await projectsAPI.updateReport(projectId, reportId, form);
      } else {
        const res = await projectsAPI.createReport(projectId, form);
        savedId = res.data.id;
      }

      // Handle Image Upload Logic (Sequential for simplicity)
      if (pendingImages.length > 0) {
        for (const img of pendingImages) {
          const fd = new FormData();
          fd.append('image', img.file);
          if (img.caption) fd.append('caption', img.caption);
          await projectsAPI.uploadReportImage(projectId, savedId, fd);
        }
      }

      toast.success(isEditing ? 'Mis à jour' : 'Rapport créé');
      navigate(`/projects/${projectId}?tab=journal`);
    } catch (err) {
      toast.error('Erreur lors de la sauvegarde');
    } finally {
      setLoading(false);
    }
  };

  // Modern UI Styles
  const sectionStyle = {
    backgroundColor: '#ffffff',
    borderRadius: '16px',
    padding: '32px',
    marginBottom: '24px',
    boxShadow: '0 4px 6px -1px rgba(0, 0, 0, 0.05), 0 2px 4px -1px rgba(0, 0, 0, 0.03)',
    border: '1px solid #f3f4f6'
  };

  const labelStyle = {
    display: 'block',
    fontSize: '13px',
    fontWeight: '600',
    color: '#4b5563',
    marginBottom: '8px',
    letterSpacing: '0.025em'
  };

  const inputStyle = {
    width: '100%',
    backgroundColor: '#f9fafb',
    border: '1px solid #e5e7eb',
    borderRadius: '10px',
    padding: '12px 16px',
    fontSize: '15px',
    color: '#111827',
    transition: 'all 0.2s ease',
    outline: 'none',
  };

  return (
    <AppLayout>
      <div style={{ backgroundColor: '#f9fafb', minHeight: '100vh', padding: '40px 20px' }}>
        <div style={{ maxWidth: '800px', margin: '0 auto' }}>

          {/* Header Area */}
          <div style={{ marginBottom: '40px' }}>
            <button onClick={() => navigate(`/projects/${projectId}`)}
              style={{ background: 'none', border: 'none', color: '#9ca3af', fontSize: '14px', cursor: 'pointer', marginBottom: '12px', display: 'flex', alignItems: 'center', gap: '8px', fontWeight: '500' }}>
              ← Retour au Projet
            </button>
            <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'flex-end' }}>
              <div>
                <h1 style={{ fontSize: '32px', fontWeight: '800', color: '#111827', margin: 0, letterSpacing: '-0.02em' }}>
                  Journal de <span style={{ color: '#F59E0B' }}>Chantier</span>
                </h1>
                <p style={{ color: '#6b7280', marginTop: '4px', fontSize: '16px' }}>
                  {isEditing ? 'Modification du rapport' : 'Nouveau point de situation quotidien'} 
                  {project && <span style={{ fontWeight: '600', color: '#374151' }}> — {project.name}</span>}
                </p>
              </div>
              <div style={{ textAlign: 'right' }}>
                <span style={{ padding: '6px 12px', borderRadius: '20px', backgroundColor: '#FEF3C7', color: '#D97706', fontSize: '12px', fontWeight: '700', textTransform: 'uppercase' }}>
                   Rapport Officiel
                </span>
              </div>
            </div>
          </div>

          <form onSubmit={handleSubmit}>

            {/* SECTION 1: Logistics */}
            <div style={sectionStyle}>
              <div style={{ display: 'grid', gridTemplateColumns: 'repeat(3, 1fr)', gap: '24px' }}>
                <div>
                  <label style={labelStyle}>DATE DU JOUR</label>
                  <input style={inputStyle} type="date" name="report_date" value={form.report_date} onChange={handleChange} required />
                </div>
                <div>
                  <label style={labelStyle}>MÉTÉO</label>
                  <select style={inputStyle} name="weather" value={form.weather} onChange={handleChange}>
                    {WEATHER_OPTIONS.map(o => <option key={o.value} value={o.value}>{o.label}</option>)}
                  </select>
                </div>
                <div>
                  <label style={labelStyle}>TEMP. (°C)</label>
                  <input style={inputStyle} type="number" name="temperature" placeholder="24" value={form.temperature} onChange={handleChange} />
                </div>
              </div>
            </div>

            {/* SECTION 2: Work Done */}
            <div style={sectionStyle}>
               <div style={{ marginBottom: '24px' }}>
                  <label style={labelStyle}>ACTIVITÉS RÉALISÉES</label>
                  <textarea 
                    style={{ ...inputStyle, minHeight: '140px', lineHeight: '1.6' }} 
                    name="work_done" 
                    value={form.work_done} 
                    onChange={handleChange} 
                    required
                    placeholder="Quelles étapes ont été franchies aujourd'hui ?" 
                  />
               </div>
               <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '24px' }}>
                  <div>
                    <label style={labelStyle}>EFFECTIFS (Pers.)</label>
                    <input style={inputStyle} type="number" name="workers_count" value={form.workers_count} onChange={handleChange} required />
                  </div>
                  <div>
                    <label style={labelStyle}>AVANCEMENT (%)</label>
                    <input style={inputStyle} type="number" name="progress_pct" value={form.progress_pct} onChange={handleChange} max="100" />
                  </div>
               </div>
            </div>

            {/* SECTION 3: Incidents & Materials */}
            <div style={sectionStyle}>
              <div style={{ marginBottom: '24px' }}>
                <label style={labelStyle}>MATÉRIAUX & ÉQUIPEMENTS</label>
                <input style={inputStyle} name="materials_used" value={form.materials_used} onChange={handleChange} placeholder="Béton B25, Grue, HA12..." />
              </div>
              <div>
                <label style={labelStyle}>ALÉAS OU INCIDENTS (SI APPLICABLE)</label>
                <textarea 
                  style={{ ...inputStyle, minHeight: '80px', border: form.incidents ? '1px solid #fca5a5' : '1px solid #e5e7eb', backgroundColor: form.incidents ? '#fffafb' : '#f9fafb' }} 
                  name="incidents" 
                  value={form.incidents} 
                  onChange={handleChange} 
                  placeholder="Retards, pannes, météo défavorable..." 
                />
              </div>
            </div>

            {/* SECTION 4: Media */}
            <div style={sectionStyle}>
              <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '20px' }}>
                <label style={{ ...labelStyle, margin: 0 }}>DOCUMENTATION PHOTOGRAPHIQUE</label>
                <button type="button" onClick={() => fileInputRef.current.click()} style={{ backgroundColor: '#111827', color: '#fff', border: 'none', padding: '8px 16px', borderRadius: '8px', fontSize: '13px', fontWeight: '600', cursor: 'pointer' }}>
                  + Ajouter Photo
                </button>
                <input ref={fileInputRef} type="file" multiple hidden onChange={handleFileSelect} />
              </div>

              <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fill, minmax(140px, 1fr))', gap: '16px' }}>
                {existingImages.map(img => (
                  <div key={img.id} style={{ height: '140px', borderRadius: '12px', overflow: 'hidden', position: 'relative', border: '1px solid #e5e7eb' }}>
                    <img src={img.image} style={{ width: '100%', height: '100%', objectFit: 'cover' }} alt="chantier" />
                    <button type="button" onClick={() => removeExisting(img.id)} style={{ position: 'absolute', top: '8px', right: '8px', background: 'rgba(255,255,255,0.9)', border: 'none', borderRadius: '50%', width: '24px', height: '24px', cursor: 'pointer', fontWeight: 'bold' }}>×</button>
                  </div>
                ))}
                {pendingImages.map((img, i) => (
                  <div key={i} style={{ height: '140px', borderRadius: '12px', overflow: 'hidden', position: 'relative', border: '2px dashed #F59E0B' }}>
                    <img src={img.preview} style={{ width: '100%', height: '100%', objectFit: 'cover', opacity: 0.6 }} alt="chantier pending" />
                    <button type="button" onClick={() => removePending(i)} style={{ position: 'absolute', top: '8px', right: '8px', background: '#F59E0B', color: '#fff', border: 'none', borderRadius: '50%', width: '24px', height: '24px', cursor: 'pointer' }}>×</button>
                  </div>
                ))}
                <div onClick={() => fileInputRef.current.click()} style={{ height: '140px', borderRadius: '12px', border: '2px dashed #d1d5db', display: 'flex', alignItems: 'center', justifyContent: 'center', cursor: 'pointer', color: '#9ca3af', fontSize: '24px' }}>
                  +
                </div>
              </div>
            </div>

            {/* Actions */}
            <div style={{ display: 'flex', gap: '16px', marginTop: '40px' }}>
              <button 
                type="button" 
                onClick={() => navigate(-1)}
                style={{ flex: 1, padding: '16px', borderRadius: '12px', border: '1px solid #e5e7eb', backgroundColor: '#fff', color: '#374151', fontWeight: '600', cursor: 'pointer' }}
              >
                Annuler
              </button>
              <button 
                type="submit" 
                disabled={loading}
                style={{ flex: 2, padding: '16px', borderRadius: '12px', border: 'none', backgroundColor: '#F59E0B', color: '#fff', fontWeight: '700', fontSize: '16px', cursor: 'pointer', boxShadow: '0 10px 15px -3px rgba(245, 158, 11, 0.3)' }}
              >
                {loading ? 'Traitement...' : isEditing ? 'Mettre à jour le Rapport' : 'Publier le Rapport'}
              </button>
            </div>

          </form>
        </div>
      </div>
    </AppLayout>
  );
}
